package org.agentfrc.lesson;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import edu.wpi.first.wpilibj.simulation.*;
class MovingSeasonTest {
 static Path out;static MovingSeasonRig.Params params;static byte[] raw;
 @BeforeAll static void setup()throws Exception{SeasonRollerTest.setup();assertNotNull(System.getenv("FRC_MOVING_OUTPUT"));out=Path.of(System.getenv("FRC_MOVING_OUTPUT"));raw=Files.readAllBytes(out.resolve("assumptions.properties"));Properties p=new Properties();p.load(new java.io.ByteArrayInputStream(raw));assertEquals(Set.of("schema","massBasis","massKg","driveSideInertiaKgM2","driveRadiusM","driveGear","driveFriction","initialGlobalBodyAndPieceVelocityMps","driveTargetMps","frame","mountOffsetXM","release","engineeringAcceptance"),p.stringPropertyNames());assertEquals("frc-moving-season-hypothesis/v1",p.getProperty("schema"));assertEquals("assumed-complete-translating-body-including-sleeves-excluding-piece",p.getProperty("massBasis"));assertEquals("world-X-translation-with-body-relative-mechanism-origin",p.getProperty("frame"));assertEquals("0",p.getProperty("mountOffsetXM"));assertEquals("no-recapture-after-first-window-departure",p.getProperty("release"));assertEquals("blocked",p.getProperty("engineeringAcceptance"));params=new MovingSeasonRig.Params(SeasonRollerTest.d(p,"massKg"),SeasonRollerTest.d(p,"driveSideInertiaKgM2"),SeasonRollerTest.d(p,"driveRadiusM"),SeasonRollerTest.d(p,"driveGear"),SeasonRollerTest.d(p,"driveFriction"),SeasonRollerTest.d(p,"initialGlobalBodyAndPieceVelocityMps"),SeasonRollerTest.d(p,"driveTargetMps"));}
 @BeforeEach void enable(){DriverStationSim.resetData();DriverStationSim.setDsAttached(true);DriverStationSim.setEnabled(true);DriverStationSim.notifyNewData();}
 @AfterEach void disable(){DriverStationSim.setEnabled(false);DriverStationSim.notifyNewData();RoboRioSim.setVInVoltage(12);}
 static List<MovingSeasonRig.Sample> run(SeasonRollerRig.Config c,MovingSeasonRig.Params p,int n,boolean fault){var a=new ArrayList<MovingSeasonRig.Sample>();try(var rig=new MovingSeasonRig(c,p,fault)){for(int i=0;i<100;i++)a.add(rig.step(true,true,n));}return a;}
 @Test void independentlyDerivedFourContactSolution(){var model=new MovingContact(2,1,.1,.01,.1,.1);var r=model.resolve(new double[]{0,0,.002,.002,-.001,.001},new double[]{.01,.01,.01,.01});assertEquals(.0002647058823529412,r.impulse()[0],1e-12);assertEquals(.0000911764705882353,r.impulse()[2],1e-12);assertEquals(.0001735294117647059,r.velocity()[0],1e-12);assertEquals(.0001823529411764706,r.velocity()[1],1e-12);assertEquals(.001735294117647059,r.velocity()[2],1e-12);assertEquals(-.000088235294117647,r.velocity()[4],1e-12);assertTrue(r.lossJ()>0);assertTrue(r.kktResidual()<1e-10);var internal=model.resolve(new double[]{0,0,.002,.002,-.001,.001},new double[]{0,0,.01,.01});assertEquals(.000025,internal.impulse()[2],1e-12);assertEquals(0,model.momentum(internal.velocity()),1e-12);}
 @Test void noGroundFrictionPreservesActualBodyPieceMomentum(){var p=new MovingSeasonRig.Params(params.mass(),params.driveJ(),params.radius(),params.gear(),0,0,0);for(var c:SeasonRollerTest.configs){var a=run(c,p,20,false);assertTrue(a.stream().anyMatch(s->s.bodyV()<0&&s.pieceV()>0));for(var s:a)assertEquals(0,s.momentum(),1e-8);}}
 @Test void allThreeMovingPrototypesRefineAndBindActualIo()throws Exception{Properties b=new Properties();b.setProperty("assumptionsSha256",SeasonRollerTest.sha(raw));b.setProperty("driveControllerClassSha256",SeasonRollerTest.sha(CoupledDriveController.class.getResourceAsStream("CoupledDriveController.class").readAllBytes()));b.setProperty("mechanismControllerClassSha256",SeasonRollerTest.sha(SeasonRollerController.class.getResourceAsStream("SeasonRollerController.class").readAllBytes()));b.setProperty("supervisorClassSha256",SeasonRollerTest.sha(MovingPrototypeController.class.getResourceAsStream("MovingPrototypeController.class").readAllBytes()));b.setProperty("engineeringAcceptance","blocked");for(var c:SeasonRollerTest.configs){var a=run(c,params,20,false);var fine=run(c,params,40,false);assertTrue(a.get(99).done(),c.type()+" moving beam sequence incomplete");double dx=0,dv=0,dw=0,db=0,di=0;StringBuilder csv=new StringBuilder("tick,bodyXM,pieceXM,relativeXM,bodyMps,pieceMps,busV,batteryA,driveBranchA,mechanismBranchA,reactionImpulseNs,mechanicalResidual,released,beamComplete\n");for(int i=0;i<a.size();i++){var s=a.get(i);var f=fine.get(i);assertEquals(s.pieceX()-s.bodyX(),s.relativeX(),1e-12);assertEquals(s.driveA()+s.mechanismA(),s.batteryA(),1e-9);assertEquals(0,s.mechanicalResidual(),1e-5);dx=Math.max(dx,Math.max(Math.abs(s.bodyX()-f.bodyX()),Math.abs(s.pieceX()-f.pieceX())));dv=Math.max(dv,Math.max(Math.abs(s.bodyV()-f.bodyV()),Math.abs(s.pieceV()-f.pieceV())));for(int k=0;k<4;k++)dw=Math.max(dw,Math.abs(s.shafts()[k]-f.shafts()[k]));db=Math.max(db,Math.abs(s.bus()-f.bus()));di=Math.max(di,Math.abs(s.batteryA()-f.batteryA()));csv.append(i).append(',').append(s.bodyX()).append(',').append(s.pieceX()).append(',').append(s.relativeX()).append(',').append(s.bodyV()).append(',').append(s.pieceV()).append(',').append(s.bus()).append(',').append(s.batteryA()).append(',').append(s.driveA()).append(',').append(s.mechanismA()).append(',').append(s.reactionImpulse()).append(',').append(s.mechanicalResidual()).append(',').append(s.released()).append(',').append(s.done()).append('\n');}assertTrue(dx<.05&&dv<.05&&dw<5&&db<.2&&di<10,"Moving development refinement");Files.writeString(out.resolve(c.season()+"-moving.csv"),csv,StandardOpenOption.CREATE_NEW);b.setProperty(c.season()+".inputSha256",SeasonRollerTest.hashes.get(c.season()));b.setProperty(c.season()+".maxPositionDifferenceM",Double.toString(dx));b.setProperty(c.season()+".maxVelocityDifferenceMps",Double.toString(dv));b.setProperty(c.season()+".maxShaftDifferenceRadps",Double.toString(dw));b.setProperty(c.season()+".maxBusDifferenceV",Double.toString(db));b.setProperty(c.season()+".maxCurrentDifferenceA",Double.toString(di));}try(var stream=Files.newOutputStream(out.resolve("moving-result.properties"),StandardOpenOption.CREATE_NEW)){b.store(stream,"Constrained moving prototype, not whole robot acceptance");}}
 @Test void simultaneousMechanismLoadUsesSameSupply(){for(var c:SeasonRollerTest.configs){MovingSeasonRig.Sample on,off;try(var r=new MovingSeasonRig(c,params,false)){on=r.step(true,true,20);}try(var r=new MovingSeasonRig(c,params,false)){off=r.step(true,false,20);}assertTrue(on.mechanismA()>0);assertEquals(0,off.mechanismA(),1e-12);assertTrue(on.bus()<off.bus());}}
 @Test void releasedWindowHasNoAutomaticRecaptureImpulse(){for(var c:SeasonRollerTest.configs){boolean released=false;for(var s:run(c,params,20,false)){if(s.released())released=true;if(released){assertTrue(s.released());assertFalse(s.engaged());assertEquals(0,s.reactionImpulse(),0);}}assertTrue(released);}}
 @Test void worldCoordinateBeamMutationIsObservable(){for(var c:SeasonRollerTest.configs){var correct=run(c,params,20,false);var wrong=run(c,params,20,true);int good=-1,bad=-1;for(int i=0;i<100;i++){if(good<0&&correct.get(i).done())good=i;if(bad<0&&wrong.get(i).done())bad=i;}assertTrue(bad>=0&&good>bad,"Wrong global beam must finish prematurely");assertTrue(wrong.get(bad).relativeX()<c.beam()+(c.type().equals("CORAL")?c.length()/2:c.outer()));}}
 @Test void disableZerosFourBranchSupplyDemandNotVelocity(){for(var c:SeasonRollerTest.configs)try(var rig=new MovingSeasonRig(c,params,false)){for(int i=0;i<5;i++)rig.step(true,true,20);var s=rig.step(false,false,20);assertEquals(0,s.batteryA(),1e-10);assertTrue(s.bodyV()!=0||s.pieceV()!=0);}}
 @Test void continuousDriveAfterTransferRemainsUnsupported()throws Exception{var c=SeasonRollerTest.configs.stream().filter(x->x.season()==2024).findFirst().orElseThrow();var error=assertThrows(IllegalArgumentException.class,()->{try(var rig=new MovingSeasonRig(c,params,false,true)){for(int i=0;i<100;i++)rig.step(true,true,20);}});assertNotNull(error.getCause());assertEquals("Unsupported regeneration",error.getCause().getMessage());Files.writeString(out.resolve("unsupported-continuous-drive.txt"),error.getMessage()+"\n"+error.getCause().getMessage()+"\n",StandardOpenOption.CREATE_NEW);}
 @Test void mechanismSensorFaultInhibitsBothSubsystems(){for(var c:SeasonRollerTest.configs)try(var rig=new MovingSeasonRig(c,params,false)){new DIOSim(8).setValue(false);var first=rig.step(true,true,20);assertTrue(first.faulted());assertFalse(first.done());assertEquals(0,first.batteryA(),1e-12);var later=rig.step(true,true,20);assertTrue(later.faulted());assertEquals(0,later.driveA(),1e-12);assertEquals(0,later.mechanismA(),1e-12);}}
 @Test void invalidDomainsAndUnknownIoMapReject(){assertThrows(IllegalArgumentException.class,()->new MovingContact(Double.NaN,1,.1,.01,.1,.1));assertThrows(IllegalArgumentException.class,()->new MovingContact(2,1,.1,.01,.1,.1).resolve(new double[6],new double[]{-1,0,0,0}));assertThrows(IllegalArgumentException.class,()->new SeasonRollerController(.05,1,0,1,6,0,1));}
}
